import{_ as a,c as d,o,aj as r}from"./chunks/framework.Id7s26SP.js";const b=JSON.parse('{"title":"Interface: DatabaseModelHandle<TRow>","description":"","frontmatter":{},"headers":[],"relativePath":"reference/primitive-functions/api/interfaces/DatabaseModelHandle.md","filePath":"reference/primitive-functions/api/interfaces/DatabaseModelHandle.md"}'),t={name:"reference/primitive-functions/api/interfaces/DatabaseModelHandle.md"};function c(n,e,s,l,h,i){return o(),d("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>primitive-functions</strong></a></p><hr><p><a href="./../globals.html">primitive-functions</a> / DatabaseModelHandle</p><h1 id="interface-databasemodelhandle-trow" tabindex="-1"><s>Interface: DatabaseModelHandle&lt;TRow&gt;</s> <a class="header-anchor" href="#interface-databasemodelhandle-trow" aria-label="Permalink to “Interface: DatabaseModelHandle&lt;TRow&gt;”">​</a></h1><p>One model on a <a href="./DatabaseHandle.html">DatabaseHandle</a>, as <code>handle.model(name)</code> returns it — the pre-db3 way to read and write a database&#39;s rows.</p><h2 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h2><p>Use a <code>ctx.db3</code> model handle.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="trow" tabindex="-1">TRow <a class="header-anchor" href="#trow" aria-label="Permalink to “TRow”">​</a></h3><p><code>TRow</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="aggregate" tabindex="-1"><s>aggregate()</s> <a class="header-anchor" href="#aggregate" aria-label="Permalink to “aggregate()”">​</a></h3><blockquote><p><strong>aggregate</strong>(<code>body</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to “body”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-1" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-1" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="batch" tabindex="-1"><s>batch()</s> <a class="header-anchor" href="#batch" aria-label="Permalink to “batch()”">​</a></h3><blockquote><p><strong>batch</strong>(<code>body</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><p>Several writes to THIS model in one request; the binding is per item.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body-1" tabindex="-1">body <a class="header-anchor" href="#body-1" aria-label="Permalink to “body”">​</a></h5><h6 id="atomic" tabindex="-1">atomic? <a class="header-anchor" href="#atomic" aria-label="Permalink to “atomic?”">​</a></h6><p><code>boolean</code></p><h6 id="operations" tabindex="-1">operations <a class="header-anchor" href="#operations" aria-label="Permalink to “operations”">​</a></h6><p><a href="./../type-aliases/ModelBatchOperation.html"><code>ModelBatchOperation</code></a>&lt;<code>TRow</code>&gt;[]</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-2" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-2" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="count" tabindex="-1"><s>count()</s> <a class="header-anchor" href="#count" aria-label="Permalink to “count()”">​</a></h3><blockquote><p><strong>count</strong>(<code>body?</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body-2" tabindex="-1">body? <a class="header-anchor" href="#body-2" aria-label="Permalink to “body?”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-3" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-3" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="delete" tabindex="-1"><s>delete()</s> <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>recordId</code>, <code>body?</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><p>Remove ONE row by the id a read handed back — <code>databases.records.delete</code>, with this handle&#39;s model bound. An optional <code>condition</code> makes it conditional, and travels untouched.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="recordid" tabindex="-1">recordId <a class="header-anchor" href="#recordid" aria-label="Permalink to “recordId”">​</a></h5><p><code>string</code></p><h5 id="body-3" tabindex="-1">body? <a class="header-anchor" href="#body-3" aria-label="Permalink to “body?”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a>&lt;{ <code>condition?</code>: <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;; <code>id?</code>: <code>never</code>; }&gt;</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-4" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-4" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="patch" tabindex="-1"><s>patch()</s> <a class="header-anchor" href="#patch" aria-label="Permalink to “patch()”">​</a></h3><blockquote><p><strong>patch</strong>(<code>recordId</code>, <code>body</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><p>Change some fields of ONE row — <code>databases.records.patch</code>, with this handle&#39;s model bound.</p><p>The record id is positional and the body may not carry another, for the same reason it may not name another model: the runtime assigns both LAST, so a body that appeared to choose either would be a lie about which row moved. <code>condition</code>, <code>stringSets</code> and the rest of the operation&#39;s own keys pass through untouched.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="recordid-1" tabindex="-1">recordId <a class="header-anchor" href="#recordid-1" aria-label="Permalink to “recordId”">​</a></h5><p><code>string</code></p><h5 id="body-4" tabindex="-1">body <a class="header-anchor" href="#body-4" aria-label="Permalink to “body”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a>&lt;{[<code>key</code>: <code>string</code>]: <code>unknown</code>; <code>data</code>: <code>Partial</code>&lt;<code>TRow</code>&gt;; <code>id?</code>: <code>never</code>; }&gt;</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-5" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-5" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="query" tabindex="-1"><s>query()</s> <a class="header-anchor" href="#query" aria-label="Permalink to “query()”">​</a></h3><blockquote><p><strong>query</strong>(<code>body?</code>): <code>Promise</code>&lt;{ <code>hasMore</code>: <code>boolean</code>; <code>items</code>: <code>TRow</code>[]; <code>nextCursor?</code>: <code>string</code>; }&gt;</p></blockquote><p>One page of this model&#39;s rows, in the decided envelope — <code>{ items, hasMore, nextCursor? }</code>, the same shape <code>ctx.doc(...)</code>, <code>ctx.users.list</code> and the client library answer. The route&#39;s own wire shape is unchanged; the SDK is where the one name lives, so shared paging code can be written once.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body-5" tabindex="-1">body? <a class="header-anchor" href="#body-5" aria-label="Permalink to “body?”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>hasMore</code>: <code>boolean</code>; <code>items</code>: <code>TRow</code>[]; <code>nextCursor?</code>: <code>string</code>; }&gt;</p><h4 id="deprecated-6" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-6" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p><hr><h3 id="save" tabindex="-1"><s>save()</s> <a class="header-anchor" href="#save" aria-label="Permalink to “save()”">​</a></h3><blockquote><p><strong>save</strong>(<code>body</code>): <code>Promise</code>&lt;<code>any</code>&gt;</p></blockquote><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="body-6" tabindex="-1">body <a class="header-anchor" href="#body-6" aria-label="Permalink to “body”">​</a></h5><p><a href="./../type-aliases/ModelScopedBody.html"><code>ModelScopedBody</code></a>&lt;{[<code>key</code>: <code>string</code>]: <code>unknown</code>; <code>data</code>: <code>Partial</code>&lt;<code>TRow</code>&gt;; <code>id?</code>: <code>string</code>; }&gt;</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>any</code>&gt;</p><h4 id="deprecated-7" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-7" aria-label="Permalink to “Deprecated”">​</a></h4><p>Use a <code>ctx.db3</code> model handle.</p>',92)])])}const m=a(t,[["render",c]]);export{b as __pageData,m as default};
